import{_ as s,l,o as e,c as i,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"租约","description":"","frontmatter":{"title":"租约","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/leases.md","filePath":"cs/leases.md","lastUpdated":1789023840000}'),h={name:"cs/leases.md"};function _(E,a,f,m,u,T){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="租约" tabindex="-1">租约 <a class="header-anchor" href="#租约" aria-label="Permalink to &quot;租约&quot;">​</a></h1><div class="epigraph"><p>租约是带期限的授权：期内持有者可当主，过期授权作废。时钟误差必须折进期限，否则会出现两个同时有效的主。</p><footer>—— 据 Gray and Cheriton, Leases: An Efficient Fault-Tolerant Mechanism for Distributed File Cache Consistency, SOSP 1989 整理</footer></div><p>上一课<a href="/cs/failure-detectors">故障检测器</a>的怀疑可以来回抖。缺口是<strong>短时的确定性</strong>：在接下来 \\(T\\) 秒内，「谁说了算」不许并行有效。本课不重写 \\(\\Diamond\\mathcal{P}\\)。后课 FLP 会说明：没有时间假设就没有这种确定性窗口——租约正是把<a href="/cs/clock-drift">物理时钟</a>的 \\(\\varepsilon\\) 请回安全论证。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存失效：服务器改文件后要通知持有副本的客户端。若客户端崩了，通知永远等不到。Gray–Cheriton：授予租约，到期后服务器可以当客户端已放弃缓存，不必等 ack。推广：领导者租约、锁租约——都是「到期即收回」，避免无限等故障。</p><p>缺口：两台机器的钟差。若颁发者认为已过期，持有者认为还剩一秒，就会双主。必须让颁发者的等待 \\(\\ge\\) 持有者的期限 \\(+ 2\\varepsilon\\) + 最大延迟（按你声明的钟模型）。单调钟不能跨机比较期限，墙钟必须带 \\(\\varepsilon\\)。</p><p><span class="marginnote">Chubby、ZooKeeper 会话、Raft 的 leader lease 变体都是这条期限算术。本课讲算术，不讲具体共识消息。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>颁发：记下 <code>expiry = now + T</code>（带误差预算）。持有者只用到 <code>now_local + T - slack</code>。续约必须在过期前完成一轮 RTT。过期后颁发者才能把同一权授给别人。</p>',9)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20G%5B%22%E9%A2%81%E5%8F%91%E8%80%85%22%5D%20--%3E%7C%22%E7%A7%9F%E7%BA%A6%20T%22%7C%20H%5B%22%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A%20%20H%20--%3E%7C%22%E7%BB%AD%E7%BA%A6%22%7C%20G%0A%20%20G%20--%3E%7C%22%E7%AD%89%20T%2B%E8%AF%AF%E5%B7%AE%22%7C%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E4%BD%8D%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与检测器：租约期内颁发者<strong>假装</strong>强准确（不把持有者当死）；过期后完备性靠等待而不是靠心跳猜。心跳仍可用于提前打破（持有者主动交还），但不能省略过期路径。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>文件缓存：写时等所有未过期租约失效或收回，再写。比逐客户端可靠 ack 更抗崩溃。元数据锁同构。对象存储、DNS TTL 是弱租约：过期后读可能旧，那是缓存语义，不是互斥授权。</p><p>时钟回拨：持有者若墙钟回拨会以为租约更长——必须用单调钟量经过时间，用颁发者的权威时间定义绝对过期。这是上一课「超时用单调钟」的直接应用。</p><p>本课不把租约写成线性一致寄存器：它只排除「两个授权重叠」。授权里的值是否线性一致，是复制课的事。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 FLP，不引入拜占庭租约（恶意持有者可以忽略过期）。不把 DHCP lease 当分布式互斥教材。后课默认：领导权、锁、缓存失效若用租约，期限算术必须含 \\(\\varepsilon\\)；没有同步假设就没有无重叠保证。下一课说明为何纯异步连「终将选出唯一主」也不能既安全又活。</p><p>租约是把部分同步<strong>局部化</strong>成一段时间的互斥，不是取消异步安全证明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>租约 = 期限化授权；过期路径代替无限等故障。</li><li>颁发者等待必须覆盖持有者期限与时钟误差。</li><li>持有者用单调钟量流逝；跨机过期用带 \\(\\varepsilon\\) 的权威时。</li><li>出处：Gray and Cheriton, SOSP 1989。</li></ul>',10))])}const P=s(h,[["render",_]]);export{A as __pageData,P as default};
